FILES = {
    "templates/prospect_concept.html": '{% extends "base.html" %}\n{% block title %}Website Concepts · {{ business.name }} · Business OS{% endblock %}\n{% block heading %}Prospect-to-Demo Studio{% endblock %}\n\n{% block actions %}\n<a class="btn secondary" href="{{ url_for(\'business_detail\', bid=business.id) }}">← Prospect Intelligence</a>\n{% endblock %}\n\n{% block content %}\n<div class="v13-workspace-hero">\n  <div>\n    <span class="section-kicker">PRIVATE SALES ASSET</span>\n    <h2>Build a website concept {{ business.name }} can actually react to.</h2>\n    <p>Public prospect facts stay fixed. Design direction can change dramatically.</p>\n  </div>\n  <div class="v13-truth-badge">\n    <strong>PUBLIC / UNVERIFIED</strong>\n    <span>Private concept only</span>\n  </div>\n</div>\n\n<section class="panel v9-panel v13-create-panel">\n  <div class="v13-create-head">\n    <div>\n      <span class="section-kicker">CREATE CONCEPT</span>\n      <h3>Direct the Creative Director</h3>\n      <p>Describe the feeling, composition, audience, or what should change. Business OS turns that into validated design decisions without inventing business facts.</p>\n    </div>\n    <span class="v13-create-status">Publishing locked</span>\n  </div>\n\n  <form method="POST" action="{{ url_for(\'generate_prospect_concept\', bid=business.id) }}" class="v13-concept-form">\n    <label>\n      <span>Creative direction</span>\n      <textarea name="creative_brief" maxlength="700" rows="5" placeholder="Example: Established tree company. Rugged and confident. Cinematic opening, earthy palette, strong typography, obvious phone path. Avoid a generic SaaS feel."></textarea>\n    </label>\n\n    <div class="v13-quick-directions" aria-label="Creative direction examples">\n      <span>Try:</span>\n      <code>premium editorial</code>\n      <code>rugged blue-collar</code>\n      <code>minimal and quiet</code>\n      <code>service-first</code>\n      <code>completely different direction</code>\n    </div>\n\n    <div class="v13-form-footer">\n      <small>Design can change layout, hierarchy, typography, palette, density and section treatment. Services, credentials, pricing, guarantees and outcomes remain off-limits unless verified.</small>\n      <button class="btn" type="submit">Generate New Concept</button>\n    </div>\n  </form>\n</section>\n\n<section class="panel v9-panel v13-sales-summary">\n  <div class="v13-sales-summary-head">\n    <div>\n      <span class="section-kicker">SALES BRIEF</span>\n      <h3>{{ sales.recommended_plan }} is the starting conversation</h3>\n      <p>{{ sales.plan_reason }}</p>\n    </div>\n    <a class="btn secondary" href="#concept-history">Jump to concepts ↓</a>\n  </div>\n\n  {% if sales.pitch_points %}\n  <div class="v13-mini-insights">\n    {% for item in sales.pitch_points[:3] %}\n    <p>{{ item }}</p>\n    {% endfor %}\n  </div>\n  {% else %}\n  <div class="v9-empty">\n    <strong>No evidence-backed pitch angle yet.</strong>\n    <span>Audit before treating weaknesses as facts.</span>\n  </div>\n  {% endif %}\n</section>\n\n<section id="concept-history" class="panel v9-panel v13-history-panel">\n  <div class="v9-section-head">\n    <div>\n      <span class="section-kicker">CONCEPT HISTORY</span>\n      <h3>Private directions</h3>\n      <p>Every concept is immutable and tenant-bound. Generate alternatives freely; nothing here publishes automatically.</p>\n    </div>\n    <span class="count-bubble">{{ concepts|length }}</span>\n  </div>\n\n  {% if concepts %}\n  <div class="v13-concept-list">\n    {% for concept in concepts %}\n    <article>\n      <div>\n        <span class="v13-concept-number">Concept {{ concept.concept_number }}</span>\n        <strong>{{ concept.blueprint.layout_family|replace(\'_\',\' \')|title }} · {{ concept.blueprint.personality|replace(\'_\',\' \')|title }}</strong>\n        <small>{{ concept.blueprint.palette|title }} · {{ concept.blueprint.type_system|title }} · {{ concept.generation_mode|replace(\'_\',\' \')|title }}</small>\n        {% if concept.blueprint.design_rationale %}\n        <span class="v13-rationale">{{ concept.blueprint.design_rationale[0] }}</span>\n        {% endif %}\n      </div>\n      <div class="v13-concept-actions">\n        <span class="v12-chip">{{ concept.truth_state|replace(\'_\',\' \')|title }}</span>\n        <a class="btn secondary" href="{{ url_for(\'prospect_concept_preview\', bid=business.id, concept_id=concept.id) }}" target="_blank" rel="noopener">Open Preview ↗</a>\n      </div>\n    </article>\n    {% endfor %}\n  </div>\n  {% else %}\n  <div class="v9-empty large">\n    <strong>No concept yet.</strong>\n    <span>Generate the first private direction above.</span>\n  </div>\n  {% endif %}\n</section>\n\n<details class="panel v9-panel v13-evidence-details">\n  <summary>Sales evidence & owner discovery</summary>\n  <div class="v13-evidence-grid">\n    <div>\n      <span class="section-kicker">DO NOT OVERCLAIM</span>\n      {% for item in sales.cautions %}<div class="v13-caution">{{ item }}</div>{% endfor %}\n      <div class="v13-caution">{{ sales.complete_plan_note }}</div>\n    </div>\n    <div>\n      <span class="section-kicker">DISCOVERY</span>\n      <div class="v13-question-list">\n        {% for item in sales.discovery_questions %}\n        <div><span>{{ loop.index }}</span><p>{{ item }}</p></div>\n        {% endfor %}\n      </div>\n    </div>\n  </div>\n</details>\n{% endblock %}\n',
    "templates/prospect_concept_preview.html": '<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <meta name="robots" content="noindex,nofollow,noarchive">\n  <title>{{ site.name }} · Private Website Concept</title>\n  <link rel="stylesheet" href="{{ url_for(\'static\', filename=\'v13.css\') }}?v=3">\n</head>\n<body class="v13-site family-{{ bp.layout_family }} palette-{{ bp.palette }} type-{{ bp.type_system }} spacing-{{ bp.spacing }} radius-{{ bp.radius }} surface-{{ bp.surface }} personality-{{ bp.personality }} motif-{{ bp.visual_motif }} density-{{ bp.density }}">\n  <aside class="v13-demo-ribbon" aria-label="Private concept status">\n    <strong>PRIVATE CONCEPT</strong>\n    <span>Preview only · not published</span>\n  </aside>\n\n  <header class="v13-site-nav nav-{{ bp.nav_style }}">\n    <a class="v13-site-brand" href="#top">{{ site.name }}</a>\n    <nav aria-label="Concept navigation">\n      <a href="#about">About</a>\n      {% if site.has_reputation %}<a href="#reputation">Reputation</a>{% endif %}\n      <a class="v13-nav-cta cta-{{ bp.cta_style }}" href="#contact">Contact</a>\n    </nav>\n  </header>\n\n  <main id="top">\n    <section class="v13-public-hero hero-{{ bp.hero_layout }}">\n      <div class="v13-hero-copy">\n        <span class="v13-eyebrow">{{ site.eyebrow }}</span>\n        <h1>{{ site.headline }}</h1>\n        <p class="v13-supporting">{{ site.supporting }}</p>\n        <p class="v13-hero-body">{{ site.hero_body }}</p>\n        <div class="v13-hero-actions">\n          {% if site.phone_href %}\n          <a class="v13-primary cta-{{ bp.cta_style }}" href="{{ site.phone_href }}">{{ site.contact_label }}</a>\n          {% else %}\n          <a class="v13-primary cta-{{ bp.cta_style }}" href="#contact">Contact</a>\n          {% endif %}\n          <a class="v13-secondary" href="#about">See details</a>\n        </div>\n      </div>\n\n      {% if bp.hero_layout not in [\'quiet_center\', \'full_statement\'] %}\n      <aside class="v13-hero-proof" aria-label="Public business details">\n        <span class="v13-proof-kicker">PUBLIC DETAILS</span>\n        <div class="v13-proof-list">\n          {% for item in site.hero_facts %}\n          <div><span>{{ item.label }}</span><strong>{{ item.value }}</strong></div>\n          {% endfor %}\n        </div>\n      </aside>\n      {% endif %}\n\n      {% if bp.hero_layout == \'full_statement\' %}\n      <div class="v13-hero-factline">\n        {% for item in site.hero_facts[:3] %}\n        <span><b>{{ item.label }}</b>{{ item.value }}</span>\n        {% endfor %}\n      </div>\n      {% endif %}\n    </section>\n\n    {% for section in site.sections %}\n      {% if section == \'credibility\' %}\n      <section id="about" class="v13-public-section credibility-{{ bp.section_variants.credibility }}">\n        <div class="v13-section-heading">\n          <span>AT A GLANCE</span>\n          <h2>The essentials, without the clutter.</h2>\n        </div>\n        <div class="v13-fact-grid">\n          <article><span>Business</span><strong>{{ site.name }}</strong></article>\n          <article><span>Category</span><strong>{{ site.category }}</strong></article>\n          {% if site.city %}<article><span>Location</span><strong>{{ site.city }}</strong></article>{% endif %}\n          {% if site.phone %}<article><span>Contact</span><strong>{{ site.phone }}</strong></article>{% endif %}\n        </div>\n      </section>\n\n      {% elif section == \'category_focus\' %}\n      <section class="v13-public-section category-{{ bp.section_variants.category_focus }}">\n        <div class="v13-category-copy">\n          <span class="v13-eyebrow">WHAT THEY DO</span>\n          <h2>{{ site.category }}</h2>\n          <p>{{ site.category_copy }}</p>\n        </div>\n        <div class="v13-category-mark" aria-hidden="true">\n          <span>{{ site.category }}</span>\n          {% if site.city %}<small>{{ site.city }}</small>{% endif %}\n        </div>\n      </section>\n\n      {% elif section == \'local_presence\' %}\n      <section class="v13-public-section local-{{ bp.section_variants.local_presence }}">\n        <div>\n          <span class="v13-eyebrow">LOCATION</span>\n          <h2>{{ site.location_heading }}</h2>\n          <p>{{ site.location_copy }}</p>\n        </div>\n        <div class="v13-local-mark" aria-hidden="true"><span>{{ site.city }}</span></div>\n      </section>\n\n      {% elif section == \'reputation\' %}\n      <section id="reputation" class="v13-public-section reputation-{{ bp.section_variants.reputation }}">\n        <div class="v13-reputation-copy">\n          <span class="v13-eyebrow">PUBLIC REPUTATION</span>\n          <h2>{{ site.reputation_heading }}</h2>\n          <p>{{ site.reputation_detail }}</p>\n        </div>\n        <div class="v13-review-pill" aria-hidden="true">\n          <strong>{{ site.rating }} ★</strong>\n          <span>{{ site.reviews }} reviews</span>\n        </div>\n      </section>\n\n      {% elif section == \'contact\' %}\n      <section id="contact" class="v13-public-section contact-{{ bp.section_variants.contact }}">\n        <div class="v13-contact-copy">\n          <span class="v13-eyebrow">NEXT STEP</span>\n          <h2>{{ site.contact_heading }}</h2>\n          <p>{{ site.contact_copy }}</p>\n        </div>\n        <div class="v13-contact-card">\n          <strong>{{ site.name }}</strong>\n          {% if site.phone %}<a href="{{ site.phone_href }}">{{ site.phone }}</a>{% endif %}\n          {% if site.city %}<span>{{ site.city }}</span>{% endif %}\n          {% if site.phone_href %}<a class="v13-contact-button" href="{{ site.phone_href }}">Call now</a>{% endif %}\n        </div>\n      </section>\n      {% endif %}\n    {% endfor %}\n  </main>\n\n  <footer class="v13-site-footer">\n    <strong>{{ site.name }}</strong>\n    <span>Private preview · not published</span>\n  </footer>\n</body>\n</html>\n',
    "static/v13.css": '/* Business OS v13 — Final visual quality pass\n   Shared operator workspace + isolated private prospect concept surface.\n   No external assets, scripts, arbitrary HTML, or fake photography. */\n\n/* ---------- Operator workspace ---------- */\n.v13-workspace-hero{\n  display:flex;align-items:center;justify-content:space-between;gap:28px;\n  padding:28px 30px;border-radius:24px;\n  background:linear-gradient(135deg,#123c31,#1e5546);color:#fff;margin-bottom:18px\n}\n.v13-workspace-hero h2{font-size:30px;line-height:1.08;margin:7px 0}\n.v13-workspace-hero p{max-width:760px;color:rgba(255,255,255,.77);margin:0}\n.v13-truth-badge{\n  flex:0 0 auto;min-width:180px;padding:15px 17px;\n  border:1px solid rgba(255,255,255,.18);border-radius:16px;background:rgba(255,255,255,.08)\n}\n.v13-truth-badge strong,.v13-truth-badge span{display:block}\n.v13-truth-badge strong{font-size:11px;letter-spacing:.1em}\n.v13-truth-badge span{font-size:11px;opacity:.7;margin-top:5px}\n\n.v13-create-panel,.v13-sales-summary,.v13-history-panel,.v13-evidence-details{\n  width:100%!important;max-width:none!important;min-width:0!important;box-sizing:border-box\n}\n.v13-create-head,.v13-sales-summary-head{\n  display:flex;justify-content:space-between;align-items:flex-start;gap:24px\n}\n.v13-create-head>div,.v13-sales-summary-head>div{min-width:0;max-width:900px}\n.v13-create-head h3,.v13-sales-summary-head h3{margin-bottom:6px}\n.v13-create-head p,.v13-sales-summary-head p{color:#6b7b75;margin:0;line-height:1.55}\n.v13-create-status{\n  flex:0 0 auto;padding:7px 10px;border-radius:999px;\n  background:#eef4f1;color:#355d4e;font-size:10px;font-weight:850;letter-spacing:.04em\n}\n.v13-concept-form{margin-top:18px}\n.v13-concept-form label{display:grid;gap:8px}\n.v13-concept-form label>span{font-size:12px;font-weight:800}\n.v13-concept-form textarea{\n  width:100%;min-height:130px;box-sizing:border-box;padding:14px 15px;\n  border:1px solid #d9e2de;border-radius:13px;background:#fbfcfb;\n  color:#17211d;font:inherit;line-height:1.5;resize:vertical\n}\n.v13-concept-form textarea:focus{outline:2px solid rgba(28,91,69,.16);border-color:#7ba191}\n.v13-quick-directions{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-top:10px}\n.v13-quick-directions span{font-size:10px;font-weight:800;color:#7a8984}\n.v13-quick-directions code{\n  font:700 10px/1 Arial,sans-serif;padding:7px 9px;border-radius:999px;\n  background:#eef4f1;color:#39584c\n}\n.v13-form-footer{\n  display:flex;justify-content:space-between;gap:18px;align-items:center;margin-top:14px\n}\n.v13-form-footer small{max-width:760px;color:#6b7b75;line-height:1.45}\n\n.v13-sales-summary{margin-top:18px}\n.v13-mini-insights{\n  display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:16px\n}\n.v13-mini-insights p{\n  margin:0!important;padding:13px 14px;border:1px solid #e2e9e6;\n  border-radius:12px;background:#fbfdfc;font-size:12px;line-height:1.5\n}\n\n.v13-history-panel{margin-top:18px}\n.v13-concept-list{display:grid}\n.v13-concept-list article{\n  display:flex;align-items:center;justify-content:space-between;gap:18px;\n  padding:15px 2px;border-top:1px solid #e7ecea\n}\n.v13-concept-list article:first-child{border-top:0}\n.v13-concept-list strong,.v13-concept-list small{display:block}\n.v13-concept-list small{color:#6b7b75;margin-top:3px}\n.v13-concept-number{\n  display:block;font-size:9px;font-weight:850;letter-spacing:.11em;color:#678078;margin-bottom:4px\n}\n.v13-rationale{display:block;max-width:760px;margin-top:7px;font-size:11px;color:#819089}\n.v13-concept-actions{display:flex;gap:9px;align-items:center;flex:0 0 auto}\n\n.v13-evidence-details{margin-top:18px}\n.v13-evidence-details>summary{cursor:pointer;font-weight:800}\n.v13-evidence-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:18px}\n.v13-caution{\n  font-size:12px;line-height:1.55;background:#fffaf1;border:1px solid #eee2c8;\n  border-radius:12px;padding:12px 13px;margin-top:8px\n}\n.v13-question-list{display:grid}\n.v13-question-list>div{\n  display:grid;grid-template-columns:28px 1fr;gap:10px;padding:11px 0;border-top:1px solid #e7ecea\n}\n.v13-question-list>div:first-child{border-top:0}\n.v13-question-list span{\n  width:24px;height:24px;border-radius:50%;display:grid;place-items:center;\n  background:#edf4f1;font-size:10px;font-weight:850\n}\n.v13-question-list p{margin:2px 0!important;font-size:12px}\n\n@media(max-width:1000px){\n  .v13-workspace-hero{align-items:flex-start;flex-direction:column}\n  .v13-truth-badge{min-width:0}\n  .v13-create-head,.v13-sales-summary-head{flex-direction:column}\n  .v13-mini-insights{grid-template-columns:1fr}\n  .v13-form-footer{align-items:flex-start;flex-direction:column}\n  .v13-concept-list article{align-items:flex-start;flex-direction:column}\n  .v13-evidence-grid{grid-template-columns:1fr}\n}\n\n/* ---------- Private prospect concept surface ---------- */\n.v13-site{\n  --ink:#17211d;--muted:#65716d;--paper:#fff;--soft:#f3f5f3;\n  --accent:#1c5b45;--accent-2:#dce9e2;--line:rgba(23,33,29,.13);\n  --max:1180px;margin:0;background:var(--paper);color:var(--ink);\n  font-family:ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;\n  -webkit-font-smoothing:antialiased\n}\n.v13-site *{box-sizing:border-box}\n.v13-site html{scroll-behavior:smooth}\n.v13-site a{color:inherit}\n.v13-site.palette-navy{--ink:#101b2b;--accent:#1e5b9f;--accent-2:#dfe8f5;--soft:#f3f6fa}\n.v13-site.palette-slate{--ink:#20272b;--accent:#455a65;--accent-2:#e4eaed;--soft:#f4f6f7}\n.v13-site.palette-sand{--ink:#2d281f;--accent:#8a6233;--accent-2:#efe3d0;--soft:#faf6ef}\n.v13-site.palette-earth{--ink:#2c251f;--accent:#6b4d37;--accent-2:#eadfd4;--soft:#f8f4ef}\n.v13-site.palette-mono{--ink:#151515;--accent:#151515;--accent-2:#e9e9e9;--soft:#f5f5f5}\n.v13-site.palette-copper{--ink:#241c18;--accent:#98572f;--accent-2:#efd9cc;--soft:#faf3ee}\n.v13-site.palette-workwear{--ink:#111820;--accent:#d96622;--accent-2:#f2ded2;--soft:#f4f5f6}\n.v13-site.type-editorial{font-family:Georgia,"Times New Roman",serif}\n.v13-site.type-humanist{font-family:"Trebuchet MS","Segoe UI",Arial,sans-serif}\n.v13-site.type-industrial{font-family:"Arial Narrow","Segoe UI",Arial,sans-serif}\n.v13-site.type-geometric{font-family:"Segoe UI",Arial,sans-serif}\n\n.v13-demo-ribbon{\n  position:relative;z-index:20;display:flex;justify-content:center;gap:10px;align-items:center;\n  min-height:28px;padding:7px 16px;background:#111;color:#fff;\n  font:10px ui-sans-serif,"Segoe UI",Arial,sans-serif\n}\n.v13-demo-ribbon strong{font-size:9px;letter-spacing:.14em}\n.v13-demo-ribbon span{opacity:.68}\n\n.v13-site-nav{\n  max-width:var(--max);margin:0 auto;padding:22px 30px;\n  display:flex;align-items:center;justify-content:space-between;gap:24px\n}\n.v13-site-nav.nav-floating{\n  margin-top:16px;border:1px solid var(--line);border-radius:999px;\n  padding:13px 18px;background:rgba(255,255,255,.94);backdrop-filter:blur(12px)\n}\n.v13-site-nav.nav-solid,.v13-site-nav.nav-utility{\n  max-width:none;padding-left:max(30px,calc((100vw - var(--max))/2));\n  padding-right:max(30px,calc((100vw - var(--max))/2));background:var(--ink);color:#fff\n}\n.v13-site-nav.nav-utility{border-bottom:4px solid var(--accent)}\n.v13-site-brand{font-weight:900;text-decoration:none;letter-spacing:-.025em}\n.v13-site-nav nav{display:flex;align-items:center;gap:22px}\n.v13-site-nav nav a{text-decoration:none;font-size:13px;font-weight:650}\n.v13-nav-cta,.v13-primary,.v13-contact-button{\n  display:inline-flex;align-items:center;justify-content:center;padding:11px 16px;\n  border-radius:999px;background:var(--accent);color:#fff!important;text-decoration:none;\n  font:800 12px ui-sans-serif,"Segoe UI",Arial,sans-serif\n}\n.v13-nav-cta.cta-outline,.v13-primary.cta-outline{\n  background:transparent;color:var(--accent)!important;border:1px solid var(--accent)\n}\n.nav-solid .v13-nav-cta.cta-outline,.nav-utility .v13-nav-cta.cta-outline{\n  color:#fff!important;border-color:rgba(255,255,255,.55)\n}\n.v13-nav-cta.cta-high_contrast,.v13-primary.cta-high_contrast{background:var(--ink);color:#fff!important}\n.family-poster .v13-primary.cta-high_contrast,.family-utility .v13-primary.cta-high_contrast{background:var(--accent)}\n\n.v13-public-hero{\n  max-width:var(--max);margin:0 auto;padding:76px 30px 86px;position:relative;\n  display:grid;grid-template-columns:minmax(0,1.18fr) minmax(300px,.82fr);gap:60px;align-items:center\n}\n.v13-hero-copy{position:relative;z-index:2;min-width:0}\n.v13-eyebrow,.v13-proof-kicker{\n  display:block;font:850 10px ui-sans-serif,"Segoe UI",Arial,sans-serif;\n  letter-spacing:.15em;color:var(--accent);text-transform:uppercase\n}\n.v13-hero-copy h1{\n  font-size:clamp(50px,6.8vw,92px);line-height:.95;letter-spacing:-.055em;\n  margin:15px 0 18px;max-width:900px;overflow-wrap:anywhere\n}\n.v13-supporting{\n  font-size:clamp(20px,2.1vw,30px);line-height:1.18;letter-spacing:-.025em;\n  max-width:720px;margin:0 0 15px\n}\n.v13-hero-body{font-size:16px;line-height:1.65;color:var(--muted);max-width:660px}\n.v13-hero-actions{display:flex;gap:11px;align-items:center;margin-top:25px;flex-wrap:wrap}\n.v13-secondary{\n  padding:11px 14px;text-decoration:none;border-bottom:1px solid var(--line);\n  font:800 12px ui-sans-serif,"Segoe UI",Arial,sans-serif\n}\n\n/* Meaningful public-facts panel replaces decorative empty placeholder art. */\n.v13-hero-proof{\n  min-width:0;padding:26px;border:1px solid var(--line);background:var(--soft);position:relative;overflow:hidden\n}\n.v13-hero-proof:after{\n  content:"";position:absolute;width:150px;height:150px;border-radius:50%;\n  right:-55px;top:-55px;background:var(--accent);opacity:.08\n}\n.radius-soft .v13-hero-proof{border-radius:24px}\n.radius-rounded .v13-hero-proof{border-radius:34px}\n.v13-proof-list{display:grid;margin-top:16px;position:relative;z-index:1}\n.v13-proof-list>div{padding:14px 0;border-top:1px solid var(--line)}\n.v13-proof-list>div:first-child{border-top:0;padding-top:0}\n.v13-proof-list span,.v13-proof-list strong{display:block}\n.v13-proof-list span{\n  margin-bottom:4px;color:var(--muted);\n  font:800 9px ui-sans-serif,"Segoe UI",Arial,sans-serif;letter-spacing:.1em;text-transform:uppercase\n}\n.v13-proof-list strong{font-size:18px;line-height:1.25;overflow-wrap:anywhere}\n\n.hero-offset_editorial{grid-template-columns:minmax(300px,.76fr) minmax(0,1.24fr);padding-top:104px;padding-bottom:104px}\n.hero-offset_editorial .v13-hero-copy{order:2}\n.hero-offset_editorial .v13-hero-proof{order:1}\n.hero-utility_band{\n  max-width:none;color:#fff;background:var(--ink);\n  padding-left:max(30px,calc((100vw - var(--max))/2));\n  padding-right:max(30px,calc((100vw - var(--max))/2));border-bottom:6px solid var(--accent)\n}\n.hero-utility_band .v13-hero-body{color:rgba(255,255,255,.72)}\n.hero-utility_band .v13-eyebrow{color:var(--accent-2)}\n.hero-utility_band .v13-hero-proof{\n  background:rgba(255,255,255,.05);border-color:rgba(255,255,255,.18);color:#fff\n}\n.hero-utility_band .v13-proof-list>div{border-color:rgba(255,255,255,.16)}\n.hero-utility_band .v13-proof-list span{color:rgba(255,255,255,.62)}\n.hero-poster_grid{\n  max-width:none;background:var(--soft);border-top:1px solid var(--line);border-bottom:1px solid var(--line);\n  padding-left:max(30px,calc((100vw - var(--max))/2));\n  padding-right:max(30px,calc((100vw - var(--max))/2));grid-template-columns:minmax(0,1.3fr) minmax(290px,.7fr)\n}\n.hero-poster_grid h1{text-transform:uppercase;max-width:820px}\n.hero-poster_grid .v13-hero-proof{background:var(--ink);color:#fff;border-color:var(--ink)}\n.hero-poster_grid .v13-proof-list>div{border-color:rgba(255,255,255,.15)}\n.hero-poster_grid .v13-proof-list span{color:rgba(255,255,255,.6)}\n.hero-quiet_center{\n  display:block;text-align:center;max-width:980px;padding-top:115px;padding-bottom:120px\n}\n.hero-quiet_center .v13-hero-copy h1,.hero-quiet_center .v13-hero-body,.hero-quiet_center .v13-supporting{\n  margin-left:auto;margin-right:auto\n}\n.hero-quiet_center .v13-hero-actions{justify-content:center}\n.hero-full_statement{display:block;padding-top:105px;padding-bottom:52px}\n.hero-full_statement h1{font-size:clamp(58px,8.2vw,112px);max-width:1080px}\n.v13-hero-factline{margin-top:60px;display:flex;gap:0;flex-wrap:wrap;border-top:1px solid var(--line)}\n.v13-hero-factline span{\n  min-width:180px;padding:16px 22px 0 0;margin-right:22px;\n  font:700 12px ui-sans-serif,"Segoe UI",Arial,sans-serif\n}\n.v13-hero-factline b{\n  display:block;margin-bottom:4px;color:var(--muted);\n  font-size:9px;letter-spacing:.1em;text-transform:uppercase\n}\n\n.v13-public-section{\n  max-width:var(--max);margin:0 auto;padding:78px 30px;border-top:1px solid var(--line)\n}\n.v13-section-heading,.v13-category-copy,.v13-reputation-copy{max-width:760px}\n.v13-section-heading>span{\n  font:850 9px ui-sans-serif,"Segoe UI",Arial,sans-serif;letter-spacing:.16em;color:var(--accent)\n}\n.v13-section-heading h2,.v13-public-section h2{\n  font-size:clamp(36px,4.3vw,56px);line-height:1.04;letter-spacing:-.04em;margin:10px 0 12px\n}\n.v13-section-heading p,.v13-public-section p{color:var(--muted);line-height:1.65}\n\n.v13-fact-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-top:28px}\n.v13-fact-grid article{min-width:0;padding:20px;border:1px solid var(--line);background:var(--paper)}\n.radius-soft .v13-fact-grid article{border-radius:16px}\n.radius-rounded .v13-fact-grid article{border-radius:24px}\n.v13-fact-grid span,.v13-fact-grid strong{display:block}\n.v13-fact-grid span{\n  font:800 9px ui-sans-serif,"Segoe UI",Arial,sans-serif;\n  letter-spacing:.12em;color:var(--muted);margin-bottom:8px;text-transform:uppercase\n}\n.v13-fact-grid strong{overflow-wrap:anywhere}\n.credibility-strip .v13-fact-grid{background:var(--ink);padding:10px}\n.credibility-strip .v13-fact-grid article{background:transparent;color:#fff;border-color:rgba(255,255,255,.14)}\n.credibility-editorial .v13-fact-grid article{border-width:0 0 1px;padding-left:0}\n\n.category-split{\n  display:grid;grid-template-columns:minmax(0,.95fr) minmax(280px,1.05fr);gap:64px;align-items:center\n}\n.category-feature_band{\n  max-width:none;padding-left:max(30px,calc((100vw - var(--max))/2));\n  padding-right:max(30px,calc((100vw - var(--max))/2));background:var(--soft)\n}\n.v13-category-mark{\n  min-height:220px;display:flex;flex-direction:column;justify-content:flex-end;\n  padding:28px;background:var(--soft);border:1px solid var(--line);overflow:hidden;position:relative\n}\n.v13-category-mark:before{\n  content:"";position:absolute;width:180px;height:180px;border-radius:50%;\n  right:-50px;top:-55px;background:var(--accent);opacity:.12\n}\n.radius-soft .v13-category-mark{border-radius:22px}\n.radius-rounded .v13-category-mark{border-radius:32px}\n.v13-category-mark span{\n  position:relative;z-index:1;font-size:clamp(38px,5vw,72px);line-height:.92;\n  letter-spacing:-.055em;font-weight:900;overflow-wrap:anywhere\n}\n.v13-category-mark small{\n  position:relative;z-index:1;margin-top:10px;color:var(--muted);\n  font:800 10px ui-sans-serif,"Segoe UI",Arial,sans-serif;letter-spacing:.08em;text-transform:uppercase\n}\n.category-statement .v13-category-mark{background:var(--accent);color:#fff;border-color:var(--accent)}\n.category-statement .v13-category-mark small{color:rgba(255,255,255,.72)}\n\n.local-panel,.local-editorial{\n  display:grid;grid-template-columns:minmax(0,1fr) minmax(280px,.8fr);gap:52px;align-items:center\n}\n.local-panel{background:var(--soft);max-width:1120px;margin-top:36px;margin-bottom:36px;border:0}\n.local-editorial{grid-template-columns:minmax(260px,.72fr) minmax(0,1.28fr)}\n.v13-local-mark{\n  min-height:190px;display:grid;place-items:center;background:var(--ink);color:#fff;\n  position:relative;overflow:hidden;padding:25px\n}\n.v13-local-mark:before{\n  content:"";position:absolute;width:180px;height:180px;border-radius:50%;\n  background:var(--accent);right:-45px;top:-50px\n}\n.v13-local-mark span{\n  position:relative;font-size:clamp(28px,4vw,48px);font-weight:900;letter-spacing:-.04em;\n  text-align:center;overflow-wrap:anywhere\n}\n\n.reputation-score,.reputation-band{\n  display:grid;grid-template-columns:minmax(0,1fr) auto;gap:48px;align-items:center\n}\n.reputation-band{\n  max-width:none;padding-left:max(30px,calc((100vw - var(--max))/2));\n  padding-right:max(30px,calc((100vw - var(--max))/2));background:var(--ink);color:#fff\n}\n.reputation-band p{color:rgba(255,255,255,.68)}\n.v13-review-pill{\n  min-width:180px;padding:22px 24px;border:1px solid var(--line);\n  display:grid;gap:3px;text-align:left;background:var(--soft)\n}\n.radius-soft .v13-review-pill{border-radius:20px}\n.radius-rounded .v13-review-pill{border-radius:28px}\n.v13-review-pill strong{font-size:clamp(32px,4vw,52px);line-height:1;letter-spacing:-.045em}\n.v13-review-pill span{font-size:12px;color:var(--muted)}\n.reputation-band .v13-review-pill{\n  background:rgba(255,255,255,.06);border-color:rgba(255,255,255,.18)\n}\n.reputation-band .v13-review-pill span{color:rgba(255,255,255,.68)}\n\n.contact-panel{\n  background:var(--ink);color:#fff;max-width:1120px;border:0;margin:46px auto\n}\n.contact-panel p{color:rgba(255,255,255,.68)}\n.contact-split,.contact-utility{\n  display:grid;grid-template-columns:minmax(0,1.15fr) minmax(280px,.85fr);gap:50px;align-items:center\n}\n.contact-utility{\n  max-width:none;padding-left:max(30px,calc((100vw - var(--max))/2));\n  padding-right:max(30px,calc((100vw - var(--max))/2));background:var(--soft)\n}\n.v13-contact-card{\n  min-width:0;padding:26px;border:1px solid var(--line);background:var(--paper);color:var(--ink);\n  display:grid;gap:8px\n}\n.radius-soft .v13-contact-card{border-radius:18px}\n.radius-rounded .v13-contact-card{border-radius:28px}\n.v13-contact-card strong{font-size:20px;overflow-wrap:anywhere}\n.v13-contact-card>a:not(.v13-contact-button){font-size:20px;font-weight:900;color:var(--accent);text-decoration:none}\n.v13-contact-card span{color:var(--muted)}\n.v13-contact-button{margin-top:10px;justify-self:start}\n\n.v13-site-footer{\n  display:flex;justify-content:space-between;gap:20px;padding:28px max(30px,calc((100vw - var(--max))/2));\n  background:var(--soft);font-size:12px;color:var(--muted)\n}\n\n/* Family-level distinction without unsafe arbitrary layout code. */\n.family-poster .v13-public-section{border-top:3px solid var(--ink)}\n.family-poster .v13-site-brand,.family-poster h1,.family-poster h2,.family-poster .v13-category-mark span{text-transform:uppercase}\n.family-editorial .v13-public-section{padding-top:96px;padding-bottom:96px}\n.family-utility .v13-fact-grid article{border-width:2px}\n.family-minimal .v13-public-section{max-width:980px}\n.family-minimal .v13-section-heading,.family-minimal .v13-category-copy{max-width:620px}\n.family-local_trust .v13-public-section{max-width:1100px}\n.surface-warm{background:#fbf8f3}\n.spacing-compact .v13-public-section{padding-top:56px;padding-bottom:56px}\n.spacing-spacious .v13-public-section{padding-top:100px;padding-bottom:100px}\n.radius-square *{border-radius:0!important}\n\n@media(max-width:900px){\n  .v13-site-nav nav a:not(.v13-nav-cta){display:none}\n  .v13-site-nav{padding:18px 20px}\n  .v13-site-nav.nav-floating{margin:12px 12px 0}\n  .v13-public-hero,.hero-offset_editorial,.hero-poster_grid,\n  .category-split,.local-panel,.local-editorial,.reputation-score,.reputation-band,\n  .contact-split,.contact-utility{\n    grid-template-columns:1fr\n  }\n  .hero-offset_editorial .v13-hero-copy,.hero-offset_editorial .v13-hero-proof{order:initial}\n  .v13-public-hero{\n    padding:58px 20px 64px;gap:28px\n  }\n  .hero-utility_band,.hero-poster_grid{\n    padding-left:20px;padding-right:20px\n  }\n  .hero-quiet_center{padding-top:82px;padding-bottom:86px}\n  .v13-hero-proof{padding:22px}\n  .v13-public-section{padding:60px 20px}\n  .category-feature_band,.reputation-band,.contact-utility{padding-left:20px;padding-right:20px}\n  .v13-fact-grid{grid-template-columns:1fr 1fr}\n  .v13-review-pill{min-width:0;justify-self:start}\n  .v13-site-footer{padding:24px 20px;flex-direction:column}\n  .v13-hero-copy h1{font-size:52px}\n}\n\n@media(max-width:540px){\n  .v13-demo-ribbon{align-items:flex-start;flex-direction:column;gap:2px}\n  .v13-site-nav{gap:12px}\n  .v13-site-brand{max-width:62%;overflow-wrap:anywhere}\n  .v13-fact-grid{grid-template-columns:1fr}\n  .v13-hero-actions{align-items:stretch;flex-direction:column}\n  .v13-primary,.v13-secondary{text-align:center}\n  .v13-hero-copy h1{font-size:44px}\n  .v13-supporting{font-size:20px}\n  .v13-hero-factline{flex-direction:column}\n  .v13-hero-factline span{margin-right:0}\n  .v13-category-mark{min-height:170px;padding:22px}\n  .v13-review-pill{width:100%}\n  .v13-concept-actions{align-items:flex-start;flex-direction:column}\n}\n',
    "services/v13_site_model.py": '"""Business OS v13 - safe prospect concept render model.\n\nThis module converts public prospect facts plus a validated design blueprint into\npresentation text. It never infers services, warranties, credentials, years in\nbusiness, pricing, service areas, availability, outcomes, or ROI.\n"""\n\nfrom __future__ import annotations\n\nimport re\n\nfrom services.v13_blueprints import validate_blueprint\nfrom services.v13_creative_director import build_fact_packet\n\n\ndef _safe_phone_href(phone):\n    digits = re.sub(r"[^0-9+]", "", str(phone or ""))\n    if not digits or len(re.sub(r"\\D", "", digits)) < 7:\n        return ""\n    return "tel:" + digits\n\n\ndef _category_label(category):\n    return str(category or "Local Service").strip() or "Local Service"\n\n\ndef _hero_body(facts, tone):\n    name = facts["name"] or "This business"\n    category = _category_label(facts["category"])\n    city = facts["city"]\n\n    if tone == "premium":\n        return (\n            f"A more considered way to present {name}"\n            + (f" in {city}" if city else "")\n            + " and make the next step easy to find."\n        )\n    if tone == "neighborly":\n        return (\n            f"A straightforward way for people"\n            + (f" in {city}" if city else "")\n            + f" to find {name} and get in touch."\n        )\n    if tone == "editorial":\n        pieces = [name, category]\n        if city:\n            pieces.append(city)\n        return " · ".join(pieces) + ". Focused, clear, and easy to navigate."\n    if tone == "practical":\n        return (\n            f"Find {name}, see the essential public details, and get in touch"\n            + (f" in {city}" if city else "")\n            + "."\n        )\n    return (\n        f"{category}"\n        + (f" in {city}" if city else "")\n        + f", with a direct path to contact {name}."\n    )\n\n\ndef _category_copy(facts, tone):\n    category = _category_label(facts["category"])\n    city = facts["city"]\n\n    if city:\n        base = f"{category} in {city}."\n    else:\n        base = f"{category}."\n\n    if tone == "premium":\n        return base + " A restrained presentation keeps the focus on the business and the next action."\n    if tone == "neighborly":\n        return base + " The essentials stay easy to find on any screen."\n    if tone == "editorial":\n        return base + " Clear hierarchy gives the business a stronger digital presence."\n    if tone == "practical":\n        return base + " Direct information and contact come first."\n    return base + " A focused layout keeps the path to contact simple."\n\n\ndef _headline_for_family(facts, family):\n    name = facts["name"] or "Local business"\n    category = _category_label(facts["category"])\n    city = facts["city"]\n\n    if family == "utility":\n        return f"A clearer way to reach {name}", "Straightforward information. Direct contact."\n    if family == "poster":\n        return name, f"{category}{(\' · \' + city) if city else \'\'}"\n    if family == "editorial":\n        return name, f"A more deliberate digital presence for {category.lower()}."\n    if family == "minimal":\n        return name, f"{category}{(\' · \' + city) if city else \'\'}"\n    if family == "local_trust":\n        return f"Meet {name}", f"{category}{(\' in \' + city) if city else \'\'}"\n    return name, f"{category}{(\' in \' + city) if city else \'\'}"\n\n\ndef build_site_model(business, blueprint):\n    validate_blueprint(blueprint)\n    facts = build_fact_packet(business)\n    tone = blueprint["copy_tone"]\n    family = blueprint["layout_family"]\n\n    category = _category_label(facts["category"])\n    city = facts["city"]\n    phone = facts["phone"]\n    rating = facts["rating"]\n\n    try:\n        reviews = int(facts["reviews"] or 0)\n    except (TypeError, ValueError):\n        reviews = 0\n\n    headline, supporting = _headline_for_family(facts, family)\n\n    sections = []\n    for name in blueprint["section_order"]:\n        if name == "reputation" and (rating in (None, "") or reviews <= 0):\n            continue\n        if name == "local_presence" and not city:\n            continue\n        sections.append(name)\n\n    hero_facts = [{"label": "Category", "value": category}]\n    if city:\n        hero_facts.append({"label": "Location", "value": city})\n    if rating not in (None, "") and reviews > 0:\n        hero_facts.append({"label": "Public rating", "value": f"{rating} ★ · {reviews} reviews"})\n    if phone:\n        hero_facts.append({"label": "Phone", "value": phone})\n\n    if rating not in (None, "") and reviews > 0:\n        reputation_heading = f"{rating} ★ from {reviews} public reviews"\n        reputation_detail = "Public rating and review count shown from the current prospect record."\n    else:\n        reputation_heading = ""\n        reputation_detail = ""\n\n    return {\n        "name": facts["name"],\n        "category": category,\n        "city": city,\n        "phone": phone,\n        "phone_href": _safe_phone_href(phone),\n        "rating": rating,\n        "reviews": reviews,\n        "eyebrow": " · ".join([part for part in (category, city) if part]),\n        "headline": headline,\n        "supporting": supporting,\n        "hero_body": _hero_body(facts, tone),\n        "category_copy": _category_copy(facts, tone),\n        "sections": sections,\n        "has_reputation": rating not in (None, "") and reviews > 0,\n        "reputation_heading": reputation_heading,\n        "reputation_detail": reputation_detail,\n        "contact_label": "Call now" if phone else "Contact",\n        "contact_heading": f"Get in touch with {facts[\'name\']}",\n        "contact_copy": "Use the public contact information below to start the conversation.",\n        "location_heading": city if city else "Local business",\n        "location_copy": (\n            f"Find {facts[\'name\']} in {city} and contact the business directly."\n            if city\n            else f"Contact {facts[\'name\']} directly."\n        ),\n        "layout_family": family,\n        "hero_facts": hero_facts,\n    }\n',
    "scripts/test_v13_visual_quality.py": 'from pathlib import Path\nimport sys\n\nROOT = Path(__file__).resolve().parent.parent\nif str(ROOT) not in sys.path:\n    sys.path.insert(0, str(ROOT))\n\nfrom services.v13_creative_director import generate_concept_blueprint\nfrom services.v13_site_model import build_site_model\n\n\ndef assert_true(label, value):\n    if not value:\n        raise AssertionError(label)\n    print(f"PASS: {label}")\n\n\ndef business(**overrides):\n    row = {\n        "id": 4,\n        "name": "Example Auto Repair",\n        "category": "Auto Repair",\n        "city": "Marlboro",\n        "phone": "(732) 555-0113",\n        "rating": 4.7,\n        "reviews": 210,\n        "audit_status": "completed",\n        "estimate_form": 0,\n        "online_booking": 0,\n        "website_chat": 0,\n        "emergency_service": 0,\n        "scheduling_mentioned": 0,\n    }\n    row.update(overrides)\n    return row\n\n\ndirector = generate_concept_blueprint(business(), "rugged practical established local shop", 8)\nsite = build_site_model(business(), director.blueprint)\n\nassert_true("site model keeps canonical name", site["name"] == "Example Auto Repair")\nassert_true("site model keeps public location", site["city"] == "Marlboro")\nassert_true("site model keeps public reputation", site["rating"] == 4.7 and site["reviews"] == 210)\nassert_true("reputation is expressed once as a composed heading", site["reputation_heading"] == "4.7 ★ from 210 public reviews")\nassert_true("hero fact panel is based only on existing prospect facts", any(item["value"] == "Auto Repair" for item in site["hero_facts"]))\nassert_true("phone action remains a safe tel link", site["phone_href"].startswith("tel:"))\n\nno_rep = build_site_model(business(rating=None, reviews=0), director.blueprint)\nassert_true("missing reputation remains omitted", no_rep["reputation_heading"] == "" and "reputation" not in no_rep["sections"])\n\npreview = (ROOT / "templates" / "prospect_concept_preview.html").read_text(encoding="utf-8")\nworkspace = (ROOT / "templates" / "prospect_concept.html").read_text(encoding="utf-8")\ncss = (ROOT / "static" / "v13.css").read_text(encoding="utf-8")\n\nfor forbidden in (\n    "Business OS for this prospect",\n    "owner-confirmed",\n    "Owner-verified",\n    "v13 deliberately refuses",\n    "This concept demonstrates",\n    "v13-visual",\n    "v13-rating-mark",\n):\n    assert_true(f"prospect-facing template omits prototype/internal artifact: {forbidden}", forbidden not in preview)\n\nassert_true("meaningful public-facts hero panel replaces empty art", "v13-hero-proof" in preview)\nassert_true("reputation uses one compact proof component", "v13-review-pill" in preview)\nassert_true("operator create action appears before sales summary", workspace.find("v13-create-panel") < workspace.find("v13-sales-summary"))\nassert_true("operator workspace no longer uses fragile two-column grid", "v13-operator-grid" not in workspace)\nassert_true("operator panels are forced to full available width", "width:100%!important" in css)\nassert_true("desktop-to-mobile breakpoint exists", "@media(max-width:900px)" in css)\nassert_true("small-phone breakpoint exists", "@media(max-width:540px)" in css)\nassert_true("CSS contains no external web asset dependency", "http://" not in css.lower() and "https://" not in css.lower())\nassert_true("CSS contains no executable URL", "javascript:" not in css.lower())\n\nprint("ALL V13 VISUAL QUALITY TESTS PASSED")\n',
    "ARCHITECTURE_V13_FINAL.md": '# Business OS v13 — Revenue Engine / Creative Director Finalization\n\n## Release stopping point\n\nv13 is complete enough to protect as a development checkpoint when the full\nautomated suite and desktop/mobile manual acceptance pass.\n\nv13 proves the commercial loop:\n\n**Prospect → evidence-backed sales brief → private website concept → alternate\ncreative direction → immutable history → human review**\n\nIt deliberately does **not** unlock production publishing, autonomous outreach,\nSMS, scheduling, receptionist actions, billing, domains/DNS, or arbitrary\nmodel-generated website code.\n\n## What v13 now owns\n\n### 1. Evidence-backed prospect workflow\nBusiness OS can discover/audit a prospect, build a truthful sales brief, and\nopen a Prospect-to-Demo Studio without silently turning public prospect facts\ninto owner-verified production truth.\n\n### 2. Structured Creative Director\nThe Creative Director chooses from a validated blueprint contract. It can vary\nlayout family, hero architecture, typography system, palette, spacing, density,\nsection order, component variants, CTA treatment, and visual personality.\n\nThe current provider is deterministic/local for reproducibility. A future LLM\nmay propose the exact same blueprint shape, but its output must pass the same\nvalidator before storage or rendering.\n\n### 3. Immutable concepts + backward compatibility\nNew concepts use blueprint schema v2. Historical v1 concepts remain immutable\nin storage and are adapted only in memory through strict validation.\n\n### 4. Safe prospect rendering\nThe renderer uses canonical/public facts already present in Business OS.\nMissing proof disappears. The prospect-facing page does not expose internal\nengineering disclaimers and does not invent services, credentials, warranties,\npricing, service area, availability, years in business, outcomes, or ROI.\n\n### 5. Visual-quality baseline\nThe final v13 pass removes fake empty "art" placeholders and replaces them with\nmeaningful fact-driven composition. Reputation is not duplicated. The\nProspect-to-Demo Studio is action-first and responsive. Website concepts have\nmultiple safe layout families while sharing a maintainable renderer.\n\n## Security / reliability invariants\n\n- No arbitrary HTML, CSS, JavaScript, iframe, event handler, or executable model output.\n- Tenant-bound concept lookup.\n- Immutable concept history.\n- v1 compatibility is read-only; stored legacy bytes are not mutated.\n- Unsupported/malformed blueprints fail closed.\n- Public/unverified prospect data never silently becomes owner-verified truth.\n- Publishing remains human-governed and locked in v13.\n- Existing provider/SMS/scheduling live-action gates remain untouched.\n- Private preview is noindex/noarchive and uses private/no-store response headers.\n\n## Manual acceptance before protection\n\nTest at least:\n1. one tree/home-service prospect,\n2. one auto/industrial prospect,\n3. one third industry.\n\nFor each:\n- Studio is usable at desktop width with no collapsed rail.\n- Generate a concept.\n- Generate a clearly different direction.\n- Preview has no broken/empty placeholder blocks.\n- Public facts are correct.\n- Missing facts are omitted.\n- Desktop hierarchy looks credible enough to show privately to an owner.\n- Browser mobile emulation around 390px has no horizontal overflow and keeps\n  contact action readable.\n\n## Deferred beyond v13\n\nThese are intentionally not required to call v13 a successful development\ncheckpoint:\n\n- External LLM Creative Director provider.\n- Real photography/media ingestion and rights/provenance controls.\n- Owner verification workflow that promotes prospect facts to production truth.\n- Production public forms and abuse/CSRF hardening.\n- Hosting/domain/DNS/publishing adapters.\n- Billing/subscriptions.\n- Automated outreach.\n- Production receptionist/SMS/scheduling unlock.\n- A/B testing and advanced analytics.\n\nThose should be separate governed workstreams rather than being smuggled into a\nvisual website release.\n\n## Commercial test\n\nThe next business milestone is not another architecture layer. It is:\n\n> Can a real owner be shown a private, accurate concept for their actual\n> business and become interested enough to continue the conversation?\n\nThat is the right validation target after this checkpoint.\n',
}


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def run_git(*args: str) -> str:
    try:
        return subprocess.check_output(
            ["git", *args], cwd=ROOT, text=True, stderr=subprocess.STDOUT
        ).strip()
    except Exception as exc:
        return f"(git unavailable: {exc})"


def main() -> None:
    print("Business OS v13 - Finalization / Visual Quality Installer")
    print(f"Repository: {ROOT}")
    print()

    if ROOT.name != "Business-OS":
        raise SystemExit("ABORT: installer must run from the Business-OS repository scripts folder.")

    print("Current branch:")
    print(run_git("branch", "--show-current"))
    print()

    print("Verifying exact post-compatibility source...")
    mismatches = []
    for rel, expected in EXPECTED.items():
        path = ROOT / rel
        if not path.exists():
            mismatches.append(f"  MISSING {rel}")
            continue
        actual = sha256(path)
        if actual != expected:
            mismatches.append(f"  CHANGED {rel}\n    expected {expected}\n    actual   {actual}")
        else:
            print(f"  OK {rel}")

    if mismatches:
        print()
        print("ABORT: exact source no longer matches the snapshot used to build this finalization.")
        print("No files were changed.")
        print("\n".join(mismatches))
        raise SystemExit(2)

    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    backup = ROOT / ".v13_backups" / f"finalization-{stamp}"
    backup.mkdir(parents=True, exist_ok=False)

    for rel in EXPECTED:
        src = ROOT / rel
        dst = backup / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, dst)

    print()
    print(f"Backup created: {backup}")

    for rel, content in FILES.items():
        path = ROOT / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8", newline="\n")

    print()
    print("PASS: Prospect-to-Demo Studio collapse removed with action-first full-width workflow")
    print("PASS: empty decorative hero placeholder replaced by public-facts composition")
    print("PASS: duplicated reputation treatment removed")
    print("PASS: prospect-facing prototype/internal copy removed")
    print("PASS: responsive desktop/tablet/mobile layout hardening installed")
    print("PASS: visual quality regression test installed")
    print("PASS: v13 final architecture/stopping-point contract written")
    print("PASS: publishing and live provider gates untouched")
    print()
    print("Next verification commands:")
    print("  python -m compileall app.py services scripts")
    print("  python scripts/test_v12_schema.py")
    print("  python scripts/test_v12_renderer.py")
    print("  python scripts/test_v13_foundation.py")
    print("  python scripts/test_v13_creative_director.py")
    print("  python scripts/test_v13_compatibility.py")
    print("  python scripts/test_v13_visual_quality.py")
    print("  git diff --check")
    print("  git status --short")
    print()
    print("Do not commit/tag until one final desktop + mobile visual acceptance pass.")


if __name__ == "__main__":
    main()
